arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1974_12.json', 'r') as f:
    data = json.load(f)

# Print top-level keys to understand structure
def print_structure(obj, indent=0):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                print_structure(v, indent + 2)
    elif isinstance(obj, list) and len(obj) > 0 and indent < 2:
        print(' ' * indent + f'[list of {len(obj)} items]')
        print_structure(obj[0], indent + 2)

print_structure(data)
"
